    /** Se o nivel isenta o cliente do frete. */
    default boolean temFreteGratis() {
        return false;
    }

    /** Se o pedido ganha brinde. */
    default boolean temBrinde(BigDecimal subtotalProdutos) {
        return false;
    }
}
